        var folders=Page(tabs,"Thư mục riêng");folders.Controls.Add(Note("Tạo thư mục mới theo tên user trên NTFS cục bộ. Chủ sở hữu=user; chỉ user, Administrators và SYSTEM có Full Control. Không thay ACL thư mục đã tồn tại và không xóa dữ liệu. Dữ liệu con kế thừa quyền riêng tư khi còn bên trong. Dùng Xuất ZIP chia sẻ để gửi ra ngoài không mang ACL nguồn; di chuyển cùng ổ có thể giữ ACL cũ. Trên ổ cục bộ, tên thư mục của user khác vẫn có thể hiển thị; ACL chặn truy cập. Ẩn theo quyền cần SMB Access-Based Enumeration phía máy chủ."));var fb=Bar();fb.Controls.AddRange(new Control[]{privateRoot,Button("Chọn gốc",()=>{using var f=new FolderBrowserDialog();if(f.ShowDialog()==DialogResult.OK)privateRoot.Text=f.SelectedPath;}),Button("Xem trước",()=>MessageBox.Show(string.Join(Environment.NewLine,Selected().Select(u=>Path.Combine(privateRoot.Text,u.Name))))),Button("Xuất ZIP chia sẻ",ExportPrivateZip),Button("Áp dụng",()=>{if(string.IsNullOrWhiteSpace(privateRoot.Text))throw new ArgumentException("Chọn thư mục gốc.");Batch("Tạo thư mục và đặt ACL tại "+privateRoot.Text,u=>UserData.PrivateFolder(u,privateRoot.Text));})});folders.Controls.Add(fb);
        var presets=Page(tabs,"Cấu hình mặc định");presets.Controls.Add(Note("Tạo bộ từ lựa chọn hiện tại: nhóm RDP, shortcut đã chọn từ user nguồn, file .reg, thư mục gốc và ánh xạ NAS của user nguồn. Mật khẩu được mã hóa gắn với máy Windows này. Áp dụng nhiều bước có thể thành công một phần; dừng tại bước lỗi của từng user và giữ sao lưu."));var pb=Bar();pb.Controls.AddRange(new Control[]{presetList,presetRdp,Button("Tạo bộ",CreatePreset),Button("Chỉnh sửa",()=>{using var editor=new PresetEditor(Preset());editor.ShowDialog(this);RefreshPresets();}),Button("Đổi tên",()=>{var p=Preset();var n=Prompt("Tên mới",p.Name);if(n!=null)Presets.Rename(p,n);RefreshPresets();}),Button("Sao chép",()=>{var p=Preset();var n=Prompt("Tên bản sao",p.Name+" - bản sao");if(n!=null)Presets.Clone(p,n);RefreshPresets();}),Button("Xóa bộ",()=>{var p=Preset();if(Confirm("Xóa bộ "+p.Name+"? Một bản sao sẽ được giữ."))Presets.Delete(p);RefreshPresets();}),Button("Xem trước",()=>MessageBox.Show(PresetPreview(Preset()))),Button("Áp dụng",()=>{var p=Preset();Batch(PresetPreview(p),u=>Presets.Apply(p,u));})});presets.Controls.Add(pb);
