    static TabPage Page(TabControl tabs,string title){var p=new TabPage(title);tabs.TabPages.Add(p);return p;}
    static FlowLayoutPanel Bar()=>new(){Dock=DockStyle.Top,AutoSize=true,WrapContents=true,Padding=new Padding(8)};
    static Label Note(string text)=>new(){Text=text,Dock=DockStyle.Top,AutoSize=false,Height=120,Padding=new Padding(10),ForeColor=Color.DarkSlateGray};
    Button Button(string title,Action action){var b=new Button(){Text=title,AutoSize=true,Margin=new Padding(4)};b.Click+=(_,_)=>Safe(action);return b;}
    void Safe(Action action){try{UseWaitCursor=true;action();}catch(Exception e){Append("LỖI: "+e.Message);MessageBox.Show(e.Message,"Không hoàn tất",MessageBoxButtons.OK,MessageBoxIcon.Error);}finally{UseWaitCursor=false;}}
    void Append(string text)=>output.AppendText(DateTime.Now.ToString("HH:mm:ss")+" "+text+Environment.NewLine);
    static bool Confirm(string text)=>MessageBox.Show(text,"Xem trước và xác nhận",MessageBoxButtons.YesNo,MessageBoxIcon.Warning)==DialogResult.Yes;
    List<LocalUser> Selected(){users.EndEdit();var list=users.Rows.Cast<DataGridViewRow>().Where(r=>r.Cells[0].Value is true).Select(r=>(LocalUser)r.DataBoundItem).ToList();if(list.Count==0)throw new ArgumentException("Chọn ít nhất một user bên trái.");return list;}
    void RefreshUsers(){var chosen=users.Rows.Cast<DataGridViewRow>().Where(r=>r.Cells[0].Value is true).Select(r=>((LocalUser)r.DataBoundItem).Sid).ToHashSet();var list=WindowsAccounts.List();users.DataSource=list;foreach(DataGridViewRow r in users.Rows)r.Cells[0].Value=chosen.Contains(((LocalUser)r.DataBoundItem).Sid);var sid=(source.SelectedItem as LocalUser)?.Sid;source.DataSource=list;source.SelectedItem=list.FirstOrDefault(u=>u.Sid==sid)??list.FirstOrDefault();}
    void Batch(string action,Action<LocalUser> apply){var targets=Selected();if(!Confirm(action+"\r\n\r\nUser đích: "+string.Join(", ",targets.Select(u=>u.Name))+"\r\nThao tác có thể thành công một phần; xem kết quả từng user."))return;foreach(var u in targets){try{apply(u);Storage.Log(action.Split(':')[0],u.Sid,true);Append(u.Name+": thành công / cấu hình NAS chờ Agent nếu có.");}catch(Exception e){Storage.Log(action.Split(':')[0],u.Sid,false,e.HResult);Append(u.Name+": THẤT BẠI, có thể đã thay đổi một phần: "+e.Message);}}RefreshUsers();}
    void CreateUser(){using var d=new Form(){Text="Tạo tài khoản Windows local",Width=440,Height=275,StartPosition=FormStartPosition.CenterParent};var panel=Bar();var name=new TextBox(){Width=250};var password=new TextBox(){Width=250,UseSystemPasswordChar=true};var apply=new CheckBox(){Text="Áp dụng bộ đang chọn sau khi tạo",AutoSize=true};panel.Controls.AddRange(new Control[]{new Label(){Text="Tên user:",AutoSize=true},name,new Label(){Text="Mật khẩu:",AutoSize=true},password,apply});var ok=new Button(){Text="Tạo",DialogResult=DialogResult.OK};panel.Controls.Add(ok);d.Controls.Add(panel);d.AcceptButton=ok;if(d.ShowDialog(this)!=DialogResult.OK)return;var n=Policy.UserName(name.Text);var p=apply.Checked?Preset():null;if(!Confirm("Tạo user thường: "+n+" (không cấp Administrator)."+(p==null?"":"\r\n"+PresetPreview(p))))return;WindowsAccounts.Create(n,password.Text);password.Clear();var user=WindowsAccounts.List().Single(u=>u.Name.Equals(n,StringComparison.OrdinalIgnoreCase));Storage.Log("CreateUser",user.Sid,true);Append("Đã tạo "+n);RefreshUsers();if(p!=null){try{Presets.Apply(p,user);Append("Đã áp dụng cấu hình.");}catch{Append("User đã tạo; áp dụng cấu hình chưa hoàn tất.");throw;}}}
    string[] Names()=>shortcuts.CheckedItems.Cast<ListViewItem>().Select(i=>i.Text).ToArray();
    LocalUser Source()=>source.SelectedItem as LocalUser??throw new ArgumentException("Chọn user nguồn.");
    void ReadShortcuts(){shortcuts.Items.Clear();shortcuts.LargeImageList!.Images.Clear();foreach(var path in UserData.Shortcuts(Source())){var n=Path.GetFileName(path);using var icon=Icon.ExtractAssociatedIcon(path);if(icon!=null)shortcuts.LargeImageList.Images.Add(n,icon);shortcuts.Items.Add(new ListViewItem(n,n));}Append("Đã đọc "+shortcuts.Items.Count+" shortcut.");}
    string ShortcutWarning(){var warnings=new List<string>();foreach(var n in Names()){var path=Path.Combine(UserData.Desktop(Source()),n);if(Path.GetExtension(n).Equals(".lnk",StringComparison.OrdinalIgnoreCase)){object? shell=null,link=null;try{shell=Activator.CreateInstance(Type.GetTypeFromProgID("WScript.Shell")!);dynamic s=shell!;link=s.CreateShortcut(path);string target=((dynamic)link).TargetPath;if(!File.Exists(target)&&!Directory.Exists(target))warnings.Add(n+": đích không tồn tại/không kiểm tra được (vẫn có thể sao chép).");}finally{if(link!=null)System.Runtime.InteropServices.Marshal.FinalReleaseComObject(link);if(shell!=null)System.Runtime.InteropServices.Marshal.FinalReleaseComObject(shell);}}}return string.Join(Environment.NewLine,warnings);}
    void PreviewDesktop()=>MessageBox.Show("Shortcut đã chọn:\r\n"+string.Join(Environment.NewLine,Names())+"\r\n"+ShortcutWarning(),"Xem trước Desktop");
    void Sync(bool remove){var names=Names();if(names.Length==0)throw new ArgumentException("Chọn shortcut.");var from=Source();var warning=ShortcutWarning();Batch((remove?"Xóa":"Thêm, không ghi đè")+" shortcut: "+string.Join(", ",names)+"\r\n"+warning,u=>Append("Sao lưu: "+UserData.Sync(from,u,names,remove)));}
    string RegistryPreview(){if(!File.Exists(regFile.Text))throw new ArgumentException("Chọn file .reg.");var changes=Policy.ParseRegistry(File.ReadAllText(regFile.Text));return string.Join(Environment.NewLine,changes.Select(c=>"HKCU\\"+c.Key+" → "+c.Name));}
    Preset Preset()=>presetList.SelectedItem as Preset??throw new ArgumentException("Chọn bộ cấu hình.");
    void RefreshPresets(){presetList.DataSource=Presets.List();}
    void CreatePreset(){var n=Prompt("Tên bộ cấu hình");if(n==null)return;Presets.Create(n,source.SelectedItem as LocalUser,Names(),string.IsNullOrWhiteSpace(regFile.Text)?null:regFile.Text,string.IsNullOrWhiteSpace(privateRoot.Text)?null:privateRoot.Text,presetRdp.Checked);RefreshPresets();Append("Đã lưu bộ cấu hình.");}
    static string PresetPreview(Preset p)=>"Bộ: "+p.Name+"\r\nNhóm RDP: "+p.Rdp+"\r\nShortcut: "+string.Join(", ",p.Shortcuts)+"\r\nRegistry: "+p.HasRegistry+"\r\nThư mục gốc: "+p.PrivateRoot+"\r\nNAS: "+string.Join(", ",p.Nas.Select(m=>m.Drive+" → "+m.Unc));
    void LegacyRefreshNas(){nasInfo.Text=string.Join(Environment.NewLine,Nas.Load().Select(m=>m.Sid+" | "+m.Drive+" → "+m.Unc+" | "+m.User));foreach(var u in WindowsAccounts.List()){try{var profile=Microsoft.Win32.Registry.LocalMachine.OpenSubKey(@"SOFTWARE\Microsoft\Windows NT\CurrentVersion\ProfileList\"+u.Sid);using(profile){var path=profile?.GetValue("ProfileImagePath") as string;if(path==null)continue;var status=Path.Combine(Environment.ExpandEnvironmentVariables(path),"AppData","Local","WinUser","nas-status.json");if(File.Exists(status) && new FileInfo(status).Length<65536 && (File.GetAttributes(status)&FileAttributes.ReparsePoint)==0)nasInfo.AppendText("\r\n"+u.Name+" (báo cáo Agent, chưa xác thực, xem thời gian): "+File.ReadAllText(status));}}catch{}}}
    void TestNas(){if(!Confirm("Thử SMB trong phiên Administrator tới "+unc.Text+"? Có thể tạo kết nối SMB tạm của phiên hiện tại; không sửa quyền trên NAS."))return;var code=Nas.Connect(new(Policy.Drive(drive.Text),Policy.Unc(unc.Text),nasUser.Text,nasPassword.Text),true);Append("Kiểm tra NAS: "+code+" — "+(code==0?"kết nối thành công":new System.ComponentModel.Win32Exception(code).Message)+" (85: trùng ổ; 1219: xung đột SMB; 1326: sai xác thực; 5: thiếu quyền).");}
    void Restore(){using var f=new FolderBrowserDialog(){InitialDirectory=Path.Combine(Storage.Root,"Backups")};if(f.ShowDialog()!=DialogResult.OK)return;if(Confirm("Khôi phục từ "+f.SelectedPath+"? Shortcut, Registry hoặc cấu hình hiện tại có thể bị thay thế.")){UserData.Restore(f.SelectedPath);Storage.Log("Restore","backup",true);Append("Đã khôi phục trong phạm vi bản sao lưu.");}}
    static string? Prompt(string title,string initial=""){using var d=new Form(){Text=title,Width=420,Height=150,StartPosition=FormStartPosition.CenterParent};var text=new TextBox(){Text=initial,Dock=DockStyle.Top};var ok=new Button(){Text="Lưu",Dock=DockStyle.Bottom,DialogResult=DialogResult.OK};d.Controls.Add(text);d.Controls.Add(ok);d.AcceptButton=ok;return d.ShowDialog()==DialogResult.OK?text.Text:null;}
}
